INSERT INTO items (id, available, category, created_at, description, extra, photo_url, price, shop_id, title, unit, promo_price, promo_until, sold_out) VALUES (1342, TRUE, 'Box', '2026-10-16T12:04:44.568479+00:00', 'Envie de te faire plaisir ce week-end ? Découvre vite la Box du week-end proposée par LES DÉLICES DE RAMSÈS SERVICES et profite de bons moments gourmands en toute simplicité.', NULL, NULL, NULL, 195, 'Box du week-end', NULL, NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO items (id, available, category, created_at, description, extra, photo_url, price, shop_id, title, unit, promo_price, promo_until, sold_out) VALUES (1020, TRUE, 'Tissu', '2026-10-12T23:10:52.590939+00:00', 'Bienvenue chez Rama-Baye ! Découvre notre magnifique voile issu de notre sélection de tissus. Viens vite le choisir pour tes prochaines tenues !', NULL, NULL, 1000, 31, 'Voile', 'Yard', NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO items (id, available, category, created_at, description, extra, photo_url, price, shop_id, title, unit, promo_price, promo_until, sold_out) VALUES (365, TRUE, 'Habille', '2026-10-08T23:15:32.544566+00:00', 'Envie de te réchauffer avec style chez Rama-Baye ? Viens vite découvrir nos pulls de qualité qui t''offriront un vrai moment de douceur au quotidien. On t''attend avec le sourire à la boutique !', '5', NULL, 10000, 31, 'pull', '/pièce', NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO items (id, available, category, created_at, description, extra, photo_url, price, shop_id, title, unit, promo_price, promo_until, sold_out) VALUES (995, TRUE, 'Produit de santé', '2026-10-11T01:00:42.114603+00:00', 'Prends soin de ta peau avec le Karité miracle disponible chez Rama-Baye. Ce produit de santé t''apportera tout le bien-être que tu mérites au quotidien. Viens vite le découvrir dans notre boutique !', '10', NULL, 3000, 31, 'Karité miracle', '/pièce', NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO items (id, available, category, created_at, description, extra, photo_url, price, shop_id, title, unit, promo_price, promo_until, sold_out) VALUES (1347, TRUE, 'Mode et vetements', '2026-10-19T11:15:38.645174+00:00', 'Envie de craquer pour une jolie robe tendance ? Viens vite découvrir notre modèle du moment chez Rama-Baye pour te faire plaisir au quotidien. On t''attend avec le sourire à la boutique !', NULL, NULL, NULL, 31, 'Robe', NULL, NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO items (id, available, category, created_at, description, extra, photo_url, price, shop_id, title, unit, promo_price, promo_until, sold_out) VALUES (1014, TRUE, 'Nue pied', '2026-10-11T22:23:51.061103+00:00', 'Découvre notre jolie paire de chaussures nue-pied chez Monde des Minis ! Parfaite pour le confort de ton enfant, elle l''accompagnera dans toutes ses belles journées. Viens vite la choisir en boutique !', '2500', NULL, 2500, 194, 'Chaussures', NULL, NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
